// @FIGURE_CODE_BEGIN
var W = 1000, H = 600;
var draw = SVG().addTo(document.getElementById('container')).size('100%', '100%').viewbox(0, 0, W, H);

// ---------- geometry state ----------
var O = { x: 70, y: 360 };
var DEG = Math.PI / 180;
var rayAngles = [10 * DEG, -7 * DEG, -17 * DEG, -33 * DEG]; // ray1(bottom)..ray4(top)

function norm(v) { var l = Math.hypot(v.x, v.y) || 1; return { x: v.x / l, y: v.y / l }; }
function rayDir(i) { return { x: Math.cos(rayAngles[i]), y: Math.sin(rayAngles[i]) }; }

// transversals (fixed lines). R line is parallel to ray1 -> R1 at infinity initially.
var Pline = { L0: { x: 660, y: 760 }, u: norm({ x: 0.10, y: -0.995 }) };
var Qline = { L0: { x: 960, y: 650 }, u: norm({ x: -0.50, y: -0.866 }) };
var Rline = { L0: { x: 1330, y: 430 }, u: rayDir(0) }; // parallel to ray1

var P = [null, null, null, null], Q = [null, null, null, null], R = [null, null, null, null];

function lineIntersect(Opt, dr, L0, dl) {
  var denom = dr.x * dl.y - dr.y * dl.x;
  if (Math.abs(denom) < 1e-9) return null;
  var a = ((L0.x - Opt.x) * dl.y - (L0.y - Opt.y) * dl.x) / denom;
  return { x: Opt.x + a * dr.x, y: Opt.y + a * dr.y };
}
function scalarAlong(L0, u, p) { return (p.x - L0.x) * u.x + (p.y - L0.y) * u.y; }
function projectOnLine(L0, u, m) {
  var t = (m.x - L0.x) * u.x + (m.y - L0.y) * u.y;
  return { x: L0.x + u.x * t, y: L0.y + u.y * t };
}

function recompute() {
  for (var i = 0; i < 4; i++) {
    var dr = rayDir(i);
    P[i] = lineIntersect(O, dr, Pline.L0, Pline.u);
    Q[i] = lineIntersect(O, dr, Qline.L0, Qline.u);
    R[i] = (i === 0) ? null : lineIntersect(O, dr, Rline.L0, Rline.u);
    if (i === 0) R[0] = null; // ray1 parallel to R line -> point at infinity
  }
}

// cross-ratio (s1,s2,s3,s4) = ((s1-s3)(s2-s4))/((s1-s4)(s2-s3)); handles one Infinity
function crossRatio4(s) {
  var inf = -1, cnt = 0;
  for (var i = 0; i < 4; i++) if (!isFinite(s[i])) { inf = i; cnt++; }
  if (cnt > 1) return NaN;
  var a = s[0], b = s[1], c = s[2], d = s[3];
  if (cnt === 0) return ((a - c) * (b - d)) / ((a - d) * (b - c));
  if (inf === 0) return (b - d) / (b - c);
  if (inf === 1) return (a - c) / (a - d);
  if (inf === 2) return (b - d) / (a - d);
  return (a - c) / (b - c); // inf===3
}
function crOf(line, pts) {
  var s = [];
  for (var i = 0; i < 4; i++) s.push(pts[i] ? scalarAlong(line.L0, line.u, pts[i]) : Infinity);
  return crossRatio4(s);
}

// ---------- drawing ----------
var raysG = draw.group(), transG = draw.group(), ptsG = draw.group(), labG = draw.group(), readG = draw.group();
var highlight = 'All';

function haloText(t) { t.attr({ 'paint-order': 'stroke', stroke: '#fff', 'stroke-width': 3, 'stroke-linejoin': 'round' }); return t; }
function makeLabel(letter, sub, x, y, anchor, color) {
  var t = labG.text('');
  var main = t.tspan(letter).attr({ 'font-family': 'Georgia, "Times New Roman", serif', 'font-style': 'italic', 'font-size': 26, fill: color || '#000' });
  if (sub != null) t.tspan(sub).attr({ 'font-family': 'Georgia, serif', 'font-size': 16, fill: color || '#000', dy: 6 });
  t.attr({ x: x, y: y, 'text-anchor': anchor || 'start' });
  return haloText(t);
}
function setOp(el, on) { el.attr('opacity', on ? 1 : 0.18); }

function drawAll() {
  raysG.clear(); transG.clear(); ptsG.clear(); labG.clear(); readG.clear();
  var dimRays = (highlight !== 'All');

  // rays
  for (var i = 0; i < 4; i++) {
    var dr = rayDir(i);
    raysG.line(O.x, O.y, O.x + dr.x * 1300, O.y + dr.y * 1300)
      .stroke({ color: '#000', width: 2.4, linecap: 'round' }).attr('opacity', dimRays ? 0.55 : 1);
  }

  function drawTrans(line, set, pts, labelDx, labelDy, anchor) {
    var on = (highlight === 'All' || highlight === set);
    var col = '#e6007e';
    var a = { x: line.L0.x - line.u.x * 260, y: line.L0.y - line.u.y * 260 };
    var b = { x: line.L0.x + line.u.x * 560, y: line.L0.y + line.u.y * 560 };
    var ln = transG.line(a.x, a.y, b.x, b.y).stroke({ color: col, width: 3.2, linecap: 'round' });
    setOp(ln, on);
    for (var i = 0; i < 4; i++) {
      var p = pts[i];
      if (!p) continue;
      var c = ptsG.circle(15).center(p.x, p.y).fill('#000').css('cursor', 'pointer');
      setOp(c, on);
      (function (set_, i_, c_) {
        c_.on('mousedown', function (e) { startDrag({ type: 'point', set: set_, idx: i_ }, e); });
        c_.on('mousemove', function (e) { showTooltip(set_ + (i_ + 1) + ' — drag along its line', e); });
        c_.on('mouseleave', hideTooltip);
      })(set, i, c);
      var lab = makeLabel(set, String(i + 1), p.x + labelDx, p.y + labelDy, anchor, on ? '#000' : '#999');
      setOp(lab, on);
    }
    return { a: a, b: b };
  }

  drawTrans(Pline, 'P', P, 12, 30, 'start');
  drawTrans(Qline, 'Q', Q, 16, 30, 'start');
  var rEnd = drawTrans(Rline, 'R', R, -4, -16, 'start');

  // R1 at infinity annotation (only when ray1 parallel to R line)
  if (!R[0]) {
    var on = (highlight === 'All' || highlight === 'R');
    var ex = rEnd.b.x, ey = rEnd.b.y;
    var ar = transG.line(ex - 46, ey, ex - 6, ey).stroke({ color: '#000', width: 2 });
    transG.polygon((ex - 6) + ',' + ey + ' ' + (ex - 18) + ',' + (ey - 6) + ' ' + (ex - 18) + ',' + (ey + 6)).fill('#000');
    var tR = labG.text('R').attr({ x: ex + 2, y: ey + 6, 'font-family': 'Georgia, serif', 'font-style': 'italic', 'font-size': 26, fill: '#000' });
    tR.tspan('1').attr({ 'font-size': 16, dy: 6 });
    tR.tspan(' → ∞').attr({ 'font-size': 22, dy: -6 });
    haloText(tR); setOp(ar, on); setOp(tR, on);
  }

  // O
  var oc = ptsG.circle(18).center(O.x, O.y).fill('#000').css('cursor', 'pointer');
  oc.on('mousedown', function (e) { startDrag({ type: 'O' }, e); });
  oc.on('mousemove', function (e) { showTooltip('Center of projection O — drag to re-fan the rays', e); });
  oc.on('mouseleave', hideTooltip);
  haloText(labG.text('O').attr({ x: O.x - 30, y: O.y + 8, 'font-family': 'Georgia, serif', 'font-style': 'italic', 'font-size': 28, fill: '#000' }));

  // readout
  var crP = crOf(Pline, P), crQ = crOf(Qline, Q), crR = crOf(Rline, R);
  var f = function (v) { return isFinite(v) ? v.toFixed(3) : '—'; };
  var bg = readG.rect(430, 30).center(W / 2, 30).fill('#ffffff').attr('opacity', 0.85).radius(6).stroke({ color: '#ccc', width: 1 });
  var rt = readG.text('').attr({ x: W / 2, y: 36, 'text-anchor': 'middle', 'font-family': 'Georgia, serif', 'font-size': 17, fill: '#111' });
  rt.tspan('CR(P) = ' + f(crP)).attr({ fill: '#e6007e' });
  rt.tspan('    CR(Q) = ' + f(crQ)).attr({ fill: '#e6007e' });
  rt.tspan('    CR(R) = ' + f(crR)).attr({ fill: '#e6007e' });
  haloText(rt);
}

// ---------- dragging ----------
var dragInfo = null;
function clientToVB(e) {
  var pt = draw.node.createSVGPoint(); pt.x = e.clientX; pt.y = e.clientY;
  var m = draw.node.getScreenCTM().inverse(); var p = pt.matrixTransform(m);
  return { x: p.x, y: p.y };
}
function startDrag(info, e) { dragInfo = info; e.preventDefault(); }
document.addEventListener('mousemove', function (e) {
  if (!dragInfo) return;
  var m = clientToVB(e);
  if (dragInfo.type === 'O') { O.x = m.x; O.y = m.y; }
  else {
    var line = dragInfo.set === 'P' ? Pline : dragInfo.set === 'Q' ? Qline : Rline;
    var np = projectOnLine(line.L0, line.u, m);
