  var rt = readG.text('').attr({ x: W / 2, y: 36, 'text-anchor': 'middle', 'font-family': 'Georgia, serif', 'font-size': 17, fill: '#111' });
  rt.tspan('CR(P) = ' + f(crP)).attr({ fill: '#e6007e' });
  rt.tspan('    CR(Q) = ' + f(crQ)).attr({ fill: '#e6007e' });
