function startDrag(info, e) { dragInfo = info; e.preventDefault(); }
document.addEventListener('mousemove', function (e) {
  if (!dragInfo) return;
  var m = clientToVB(e);
  if (dragInfo.type === 'O') { O.x = m.x; O.y = m.y; }
  else {
    var line = dragInfo.set === 'P' ? Pline : dragInfo.set === 'Q' ? Qline : Rline;
    var np = projectOnLine(line.L0, line.u, m);
    rayAngles[dragInfo.idx] = Math.atan2(np.y - O.y, np.x - O.x);
  }
  recompute(); drawAll();
});
document.addEventListener('mouseup', function () { dragInfo = null; });

// ---------- highlight ----------
function setHighlight(state) {
  highlight = state;
  document.getElementById('highlightSetInput').textContent = 'Highlight: ' + state;
  drawAll();
}
function cycleHighlight() {
  var order = ['All', 'P set', 'Q set', 'R set'];
  var i = order.indexOf(highlight);
  setHighlight(order[(i + 1) % order.length]);
}

// ---------- demo steps ----------
var steps = [
  { title: 'One invariant, three lines', narration: 'P, Q and R are three collinear four-point sets that are projections of one another through O; the readout shows CR(P) = CR(Q) = CR(R), the projective invariant.', state: { highlightSet: 'All' } },
  { title: 'Inspect each set', narration: 'Highlight the P set, then Q, then R: each transversal’s four points yield the identical cross-ratio, confirming the value travels unchanged across the projection.', state: { highlightSet: 'P set' } },
  { title: 'Drag the points', narration: 'Drag P, Q or R points along their lines: every cross-ratio value updates live, but the three stay locked equal — the invariant survives any motion of the points on their lines.', state: {} },
  { title: 'Drag the center, note R1 at infinity', narration: 'Drag O to a new location and the whole projection re-fans while the cross-ratios remain equal; notice R1 sits at infinity because its transversal is parallel to the bottom ray, yet the invariant still holds (reducing to a simple ratio).', state: { highlightSet: 'R set' } }
];
var curStep = 0;
function setStep(i) {
  curStep = Math.max(0, Math.min(steps.length - 1, i));
  var s = steps[curStep];
  document.getElementById('demoNarration').textContent = s.narration;
  document.getElementById('stepLabel').textContent = (curStep + 1) + ' / ' + steps.length;
  if (s.state && s.state.highlightSet) setHighlight(s.state.highlightSet);
}
function nextStep() { setStep(curStep + 1); }
function prevStep() { setStep(curStep - 1); }

// ---------- init ----------
recompute();
drawAll();
setStep(0);
window.__markRendered();
// @FIGURE_CODE_END

