// @FIGURE_CODE_BEGIN
var W = 1000, H = 600;
var draw = SVG().addTo(document.getElementById('container')).size('100%', '100%').viewbox(0, 0, W, H);

// ---------- geometry state (wide ray fan matched to source composition) ----------
var O = { x: 58, y: 366 };
var DEG = Math.PI / 180;
// ray1 = bottom (steep down), ray4 = top (steep up) — wide spread like the source
var rayAngles = [24 * DEG, 4 * DEG, -14 * DEG, -40 * DEG];

function norm(v) { var l = Math.hypot(v.x, v.y) || 1; return { x: v.x / l, y: v.y / l }; }
function rayDir(i) { return { x: Math.cos(rayAngles[i]), y: Math.sin(rayAngles[i]) }; }

// Transversals. P near-vertical, Q steep diagonal, R shallow & parallel to ray1 (=> R1 at infinity).
var Pline = { L0: { x: 300, y: 430 }, u: norm({ x: 0.06, y: -0.998 }) };
var Qline = { L0: { x: 500, y: 400 }, u: norm({ x: -0.49, y: -0.87 }) };
var Rline = { L0: { x: 430, y: 150 }, u: rayDir(0) }; // parallel to bottom ray

var P = [null, null, null, null], Q = [null, null, null, null], R = [null, null, null, null];

function lineIntersect(Opt, dr, L0, dl) {
  var denom = dr.x * dl.y - dr.y * dl.x;
  if (Math.abs(denom) < 1e-9) return null;
  var a = ((L0.x - Opt.x) * dl.y - (L0.y - Opt.y) * dl.x) / denom;
  if (a < 0) return null;
  return { x: Opt.x + a * dr.x, y: Opt.y + a * dr.y };
}
function scalarAlong(L0, u, p) { return (p.x - L0.x) * u.x + (p.y - L0.y) * u.y; }
function projectOnLine(L0, u, m) {
  var t = (m.x - L0.x) * u.x + (m.y - L0.y) * u.y;
  return { x: L0.x + u.x * t, y: L0.y + u.y * t };
}

function recompute() {
  Rline.u = rayDir(0);
  for (var i = 0; i < 4; i++) {
    var dr = rayDir(i);
    P[i] = lineIntersect(O, dr, Pline.L0, Pline.u);
    Q[i] = lineIntersect(O, dr, Qline.L0, Qline.u);
    R[i] = (i === 0) ? null : lineIntersect(O, dr, Rline.L0, Rline.u);
  }
}

function crossRatio4(s) {
  var inf = -1, cnt = 0;
  for (var i = 0; i < 4; i++) if (!isFinite(s[i])) { inf = i; cnt++; }
  if (cnt > 1) return NaN;
  var a = s[0], b = s[1], c = s[2], d = s[3];
  if (cnt === 0) return ((a - c) * (b - d)) / ((a - d) * (b - c));
  if (inf === 0) return (b - d) / (b - c);
  if (inf === 1) return (a - c) / (a - d);
  if (inf === 2) return (b - d) / (a - d);
  return (a - c) / (b - c);
}
function crOf(line, pts) {
  var s = [];
  for (var i = 0; i < 4; i++) s.push(pts[i] ? scalarAlong(line.L0, line.u, pts[i]) : Infinity);
  return crossRatio4(s);
}

