var highlight = 'All';

function haloText(t) { t.attr({ 'paint-order': 'stroke', stroke: '#fff', 'stroke-width': 4, 'stroke-linejoin': 'round' }); return t; }

// Big bold serif labels (letter ~34, subscript ~19) to match the source's weight.
